+export function deepEqual(a, b, seen = new Map()) {
+  if (Object.is(a, b)) return true;
+  if (typeof a !== 'object' || typeof b !== 'object' || a === null || b === null) {
+    return false;
+  }
+
+  // Cycle handling: if we've already started comparing this pair, assume equal
+  // (self-cycles converge to true; distinct structures still fail elsewhere).
+  const prior = seen.get(a);
+  if (prior && prior.has(b)) return true;
+  if (prior) prior.add(b);
+  else seen.set(a, new Set([b]));
+
+  const tagA = Object.prototype.toString.call(a);
+  const tagB = Object.prototype.toString.call(b);
+  if (tagA !== tagB) return false;
+
+  if (a instanceof Date) return a.getTime() === b.getTime();
+  if (a instanceof RegExp) return a.source === b.source && a.flags === b.flags;
+
+  if (a instanceof Map) {
+    if (b.size !== a.size) return false;
+    for (const [k, v] of a) {
+      if (!b.has(k)) {
+        // Fall back to structural key matching for non-reference keys.
+        let matched = false;
+        for (const [bk, bv] of b) {
+          if (deepEqual(k, bk, seen) && deepEqual(v, bv, seen)) { matched = true; break; }
+        }
+        if (!matched) return false;
+      } else if (!deepEqual(v, b.get(k), seen)) {
+        return false;
+      }
+    }
+    return true;
+  }
+
+  if (a instanceof Set) {
+    if (b.size !== a.size) return false;
+    const remaining = [...b];
+    for (const v of a) {
+      const i = remaining.findIndex((w) => deepEqual(v, w, seen));
+      if (i === -1) return false;
+      remaining.splice(i, 1);
+    }
+    return true;
+  }
+
+  if (Array.isArray(a)) {
+    if (a.length !== b.length) return false;
+    for (let i = 0; i < a.length; i++) {
+      if (!deepEqual(a[i], b[i], seen)) return false;
+    }
+    return true;
+  }
+
+  const keysA = Object.keys(a);
+  const keysB = Object.keys(b);
+  if (keysA.length !== keysB.length) return false;
+  for (const k of keysA) {
+    if (!Object.prototype.hasOwnProperty.call(b, k)) return false;
+    if (!deepEqual(a[k], b[k], seen)) return false;
+  }
+  return true;
+}
