+import assert from 'node:assert';
+class TokenBucket {
+  constructor(rate, capacity, now = () => Date.now()) {
+    this.rate = rate;
+    this.capacity = capacity;
+    this.now = now;
+    this.tokens = capacity;
+    this.last = now();
+  }
+  
+  take(n = 1) {
+    const current = this.now();
+    // what if we just compute elapsed from start, and keep a running total of tokens taken?
+    if (!this.start) this.start = this.last;
+    const elapsed = (current - this.start) / 1000;
+    // total tokens ever produced
+    const totalTokens = this.capacity + elapsed * this.rate;
+    // wait, if we hit capacity, we LOSE tokens. We must cap it.
+    
+    // standard algorithm:
+    const elapsedSinceLast = (current - this.last) / 1000;
+    this.tokens += elapsedSinceLast * this.rate;
+    if (this.tokens > this.capacity) this.tokens = this.capacity;
+    this.last = current;
+    
+    // check if it passes:
+    if (this.tokens >= n) {
+      this.tokens -= n;
+      return true;
+    }
+    return false;
+  }
+}
+
+let now = 0;
+const clock = () => now;
+const b = new TokenBucket(1, 5, clock);
+try {
+  assert.strictEqual(b.take(5), true, "1");
+  assert.strictEqual(b.take(1), false, "2");
+  now = 1000;
+  assert.strictEqual(b.take(1), true, "3");
+  assert.strictEqual(b.take(5), false, "4");
+  now = 5000;
+  assert.strictEqual(b.take(5), true, "5");
