+export function deepEqual(a, b, visited = new Map()) {
+  if (Object.is(a, b)) return true;
+
+  if (typeof a !== 'object' || a === null || typeof b !== 'object' || b === null) {
+    return false;
+  }
+
+  if (Object.getPrototypeOf(a) !== Object.getPrototypeOf(b)) {
+    return false;
+  }
+
+  if (visited.has(a)) {
+    return visited.get(a) === b;
+  }
+  visited.set(a, b);
+
+  if (a instanceof Date) {
+    return Object.is(a.getTime(), b.getTime());
+  }
+
+  if (a instanceof RegExp) {
+    return a.source === b.source && a.flags === b.flags;
+  }
+
+  if (a instanceof Map) {
+    if (a.size !== b.size) return false;
+    const aEntries = Array.from(a.entries());
+    const bEntries = Array.from(b.entries());
+    const bMatched = new Array(bEntries.length).fill(false);
+
+    for (const [ak, av] of aEntries) {
+      let found = false;
+      for (let i = 0; i < bEntries.length; i++) {
+        if (!bMatched[i]) {
+          const [bk, bv] = bEntries[i];
+          if (deepEqual(ak, bk, visited) && deepEqual(av, bv, visited)) {
+            bMatched[i] = true;
+            found = true;
+            break;
+          }
+        }
+      }
+      if (!found) return false;
+    }
+    return true;
+  }
+
+  if (a instanceof Set) {
+    if (a.size !== b.size) return false;
+    const aValues = Array.from(a.values());
+    const bValues = Array.from(b.values());
+    const bMatched = new Array(bValues.length).fill(false);
+
+    for (const av of aValues) {
+      let found = false;
+      for (let i = 0; i < bValues.length; i++) {
+        if (!bMatched[i]) {
+          const bv = bValues[i];
+          if (deepEqual(av, bv, visited)) {
+            bMatched[i] = true;
+            found = true;
+            break;
+          }
+        }
+      }
+      if (!found) return false;
+    }
+    return true;
+  }
+
+  const keysA = Reflect.ownKeys(a);
+  const keysB = Reflect.ownKeys(b);
+
+  if (keysA.length !== keysB.length) return false;
+
+  for (let i = 0; i < keysA.length; i++) {
+    const key = keysA[i];
+    if (!Object.prototype.hasOwnProperty.call(b, key)) return false;
+    if (!deepEqual(a[key], b[key], visited)) return false;
+  }
+
+  return true;
+}

