+// Circular reference counter, populated during deepEqual traversals.
+let cycleCount = 0;
+
+/**
+ * Deep structural equality with cycle detection.
+ *
+ * Handles primitives, arrays, plain objects, Date, RegExp, Map, and Set.
+ * Circular references are tracked: a self-cycle on both sides compares
+ * equal, but two structurally distinct cycles compare unequal.
+ */
+export function deepEqual(a, b) {
+  cycleCount = 0;
+  return deepEqualInner(a, b, new Map());
+}
+
+/**
+ * Returns the number of circular reference encounters during the most
+ * recent deepEqual invocation. Useful for diagnostics and tests.
+ */
+export function references() {
+  return cycleCount;
+}
+
+function deepEqualInner(a, b, visited) {
+  // Fast paths for primitives and identical references.
+  if (a === b) return true;
+
+  // NaN !== NaN under ===, but NaN should be considered equal to itself.
+  if (typeof a === 'number' && typeof b === 'number') {
+    if (Number.isNaN(a) && Number.isNaN(b)) return true;
+    return false;
+  }
+
+  // If either side is null/undefined or a non-object primitive at this point
+  // (after the === fast path), they cannot be deep-equal.
+  if (
+    a === null ||
+    b === null ||
+    typeof a !== 'object' ||
+    typeof b !== 'object'
+  ) {
+    return false;
+  }
+
+  // Reject mismatched object kinds (e.g. Array vs Map, Date vs plain object).
+  const tagA = Object.prototype.toString.call(a);
+  const tagB = Object.prototype.toString.call(b);
+  if (tagA !== tagB) return false;
+
+  // Cycle detection: if we have already started comparing `a` against `b`,
+  // assume they are equal here (the outer call will validate). This lets
+  // self-referential structures compare equal to themselves and to other
+  // structures with the same shape, while breaking out of real cycles.
+  if (visited.has(a)) {
+    cycleCount++;
+    return visited.get(a) === b;
+  }
+  visited.set(a, b);
+
+  if (a instanceof Date) {
+    return a.getTime() === b.getTime();
+  }
+
+  if (a instanceof RegExp) {
+    return a.source === b.source && a.flags === b.flags;
+  }
+
+  if (a instanceof Map) {
+    if (a.size !== b.size) return false;
+    for (const [key, value] of a) {
+      if (!b.has(key)) return false;
+      if (!deepEqualInner(value, b.get(key), visited)) return false;
+    }
+    return true;
+  }
+
+  if (a instanceof Set) {
+    if (a.size !== b.size) return false;
+    // Sets are unordered, so try to match each element of `a` against some
+    // remaining element of `b` using deep equality.
+    const remaining = Array.from(b);
+    for (const item of a) {
+      let matched = false;
+      for (let i = 0; i < remaining.length; i++) {
+        if (deepEqualInner(item, remaining[i], visited)) {
+          remaining.splice(i, 1);
+          matched = true;
+          break;
+        }
+      }
+      if (!matched) return false;
+    }
+    return true;
+  }
+
+  if (Array.isArray(a)) {
+    if (a.length !== b.length) return false;
+    for (let i = 0; i < a.length; i++) {
+      if (!deepEqualInner(a[i], b[i], visited)) return false;
+    }
+    return true;
+  }
+
+  // Plain object comparison.
+  const keysA = Object.keys(a);
+  const keysB = Object.keys(b);
+  if (keysA.length !== keysB.length) return false;
+  for (const key of keysA) {
+    if (!Object.prototype.hasOwnProperty.call(b, key)) return false;
+    if (!deepEqualInner(a[key], b[key], visited)) return false;
+  }
+  return true;
