+  d(); // resets the timer
+  await sleep(30); // total ~50ms from first call; original timer would have fired here
+  assert.strictEqual(calls, 0, `call fired too early (got ${calls})`);
+  await sleep(40); // now well past the reset window
+  assert.strictEqual(calls, 1, `expected exactly 1 call after wait, got ${calls}`);
