+  const typeA = typeof a;
+  const typeB = typeof b;
+  if (typeA !== 'object' && typeB !== 'object') return Object.is(a, b);
+  if (typeA !== 'object' || typeB !== 'object') return false;
+
+  // Initialize cycle detection map
+  if (!seen) seen = new Map();
+
+  // Check if we've seen this pair before (cycle)
+  if (seen.has(a)) {
+    return seen.get(a) === b;
+  }
+  seen.set(a, b);
+
