+  // Map
+  if (a instanceof Map && b instanceof Map) {
+    if (a.size !== b.size) return false;
+    for (const [key, val] of a) {
+      if (!b.has(key)) return false;
+      if (!deepEqual(val, b.get(key), seen)) return false;
+    }
+    return true;
+  }
+
+  // Set
+  if (a instanceof Set && b instanceof Set) {
+    if (a.size !== b.size) return false;
+    // Convert to arrays so we can do O(n²) matching with deep equality
+    const arrA = [...a];
+    const arrB = [...b];
+    const matched = new Array(arrB.length).fill(false);
+    for (const elemA of arrA) {
+      let found = false;
+      for (let i = 0; i < arrB.length; i++) {
+        if (!matched[i] && deepEqual(elemA, arrB[i], seen)) {
+          matched[i] = true;
+          found = true;
+          break;
+        }
+      }
+      if (!found) return false;
+    }
+    return true;
+  }
+
+  // Array
+  if (Array.isArray(a) && Array.isArray(b)) {
+    if (a.length !== b.length) return false;
+    for (let i = 0; i < a.length; i++) {
+      if (!deepEqual(a[i], b[i], seen)) return false;
