+import { debounce } from './src/debounce.correct.js';
 import assert from 'node:assert';
+
+const sleep = ms => new Promise(resolve => setTimeout(resolve, ms));
+
+// Test 1: debounce delays the function call
+{
+  let called = 0;
+  const fn = () => { called++; };
+  const debounced = debounce(fn, 50);
+  debounced();
+  assert.strictEqual(called, 0, 'fn should not be called immediately');
+  await sleep(70);
+  assert.strictEqual(called, 1, 'fn should be called after the delay');
+}
+
+// Test 2: multiple rapid calls only result in one fn call
+{
+  let called = 0;
+  const fn = () => { called++; };
+  const debounced = debounce(fn, 50);
+  debounced();
+  debounced();
+  debounced();
+  assert.strictEqual(called, 0, 'fn should not be called immediately after rapid calls');
+  await sleep(70);
+  assert.strictEqual(called, 1, 'fn should only be called once after rapid calls');
+}
+
+// Test 3: trailing edge — the last set of arguments wins
+{
+  let lastArg = null;
+  const fn = (x) => { lastArg = x; };
+  const debounced = debounce(fn, 50);
+  debounced(1);
+  debounced(2);
+  debounced(3);
+  await sleep(70);
+  assert.strictEqual(lastArg, 3, 'last argument should be used');
+}
+
+// Test 4: each burst triggers exactly one call after its own quiet period
+{
+  let called = 0;
+  const fn = () => { called++; };
+  const debounced = debounce(fn, 30);
+  debounced();
+  debounced();
+  await sleep(50);
+  assert.strictEqual(called, 1, 'first burst should produce one call');
+  debounced();
+  debounced();
+  await sleep(50);
+  assert.strictEqual(called, 2, 'second burst should produce another call');
+}
+
+// Test 5: debounce passes all arguments through
+{
+  let captured = null;
+  const fn = (a, b, c) => { captured = [a, b, c]; };
+  const debounced = debounce(fn, 30);
+  debounced('x', 'y', 'z');
+  await sleep(50);
+  assert.deepStrictEqual(captured, ['x', 'y', 'z'], 'all arguments should be passed through');
+}
+
 console.log('debounce tests passed');

